    10	public class CorporatePlan extends RatePlan {
    11	    private static final Map<String, Double> COMPANY_DISCOUNTS = new HashMap<>();
    12	
    13	    static {
    14	        COMPANY_DISCOUNTS.put("TECNOSUL", 0.12);
    15	        COMPANY_DISCOUNTS.put("AGROVALE", 0.18);
    16	        COMPANY_DISCOUNTS.put("FARMAVIDA", 0.25);
    17	    }
    18	
    19	    private final String companyCode;
    20	
    21	    public CorporatePlan(String companyCode) {
    22	        this.companyCode = companyCode;
    23	    }
    24	
    25	    @Override
    26	    public String getPlanName() {
    27	        return "CORPORATE";
    28	    }
    29	
    30	    @Override
    31	    public void validate(Room room, LocalDate checkIn, LocalDate checkOut,
    32	                        int guests, String companyCode) {
    33	        if (companyCode == null || !COMPANY_DISCOUNTS.containsKey(companyCode)) {
    34	            throw new IllegalArgumentException("Invalid company code");
    35	        }
    36	    }
    37	
    38	    @Override
    39	    public PriceCalculation calculatePrices(Room room, LocalDate checkIn, LocalDate checkOut) {
    40	        double discountRate = COMPANY_DISCOUNTS.get(companyCode);
    41	
    42	        double subtotal = 0.0;
    43	        LocalDate current = checkIn;
    44	
    45	        while (current.isBefore(checkOut)) {
    46	            double nightlyRate = room.getNightlyRate();
    47	            if (DateUtils.isHighSeason(current)) {
    48	                nightlyRate *= 1.20;
    49	            }
    50	            subtotal += Money.round(nightlyRate);
    51	            current = current.plusDays(1);
    52	        }
    53	
    54	        subtotal = Money.round(subtotal);
    55	        double discount = Money.round(subtotal * discountRate);
    56	        double total = Money.round(subtotal - discount);
    57	
    58	        return new PriceCalculation(subtotal, discount, total);
    59	    }
    60	
    61	    @Override
    62	    public double calculateRefund(double amountPaid) {
    63	        return amountPaid;
    64	    }
    65	}
