     4	    public static RatePlan create(String planName, String companyCode) throws IllegalArgumentException {
     5	        return switch (planName) {
     6	            case "STANDARD" -> new StandardPlan();
     7	            case "NON_REFUNDABLE" -> new NonRefundablePlan();
     8	            case "CORPORATE" -> new CorporatePlan(companyCode);
