    11	public class WeekendPackagePlan extends RatePlan {
    12	    private static final Map<RoomType, Double> PACKAGE_PRICES = new HashMap<>();
    13	
    14	    static {
    15	        PACKAGE_PRICES.put(RoomType.STANDARD, 520.00);
    16	        PACKAGE_PRICES.put(RoomType.DELUXE, 820.00);
    17	        PACKAGE_PRICES.put(RoomType.SUITE, 1200.00);
    18	    }
    19	
    20	    @Override
    21	    public String getPlanName() {
    22	        return "WEEKEND_PACKAGE";
    23	    }
    24	
    25	    @Override
    26	    public void validate(Room room, LocalDate checkIn, LocalDate checkOut,
    27	                        int guests, String companyCode) {
    28	        if (!DateUtils.isFriday(checkIn)) {
    29	            throw new IllegalArgumentException("Check-in must be on Friday");
    30	        }
    31	
    32	        LocalDate expectedCheckOut = DateUtils.nextSunday(checkIn);
    33	        if (!checkOut.equals(expectedCheckOut)) {
    34	            throw new IllegalArgumentException("Check-out must be on Sunday");
    35	        }
    36	
    37	        int nights = DateUtils.countNights(checkIn, checkOut);
    38	        if (nights != 2) {
    39	            throw new IllegalArgumentException("Weekend package must be exactly 2 nights");
    40	        }
    41	    }
    42	
    43	    @Override
    44	    public PriceCalculation calculatePrices(Room room, LocalDate checkIn, LocalDate checkOut) {
    45	        double packagePrice = PACKAGE_PRICES.get(room.getType());
    46	        return new PriceCalculation(packagePrice, 0.0, packagePrice);
    47	    }
    48	
    49	    @Override
    50	    public double calculateRefund(double amountPaid) {
    51	        return Money.round(amountPaid * 0.5);
    52	    }
    53	}
