    12	public class ReservationService {
    13	    private final Map<Integer, Room> rooms = new HashMap<>();
    14	    private final Map<Long, Reservation> reservations = new HashMap<>();
    15	    private long nextReservationId = 1;
    16	
    17	    public ReservationService() {
    18	        initializeRooms();
    19	    }
    20	
    21	    private void initializeRooms() {
    22	        rooms.put(101, new Room(101, RoomType.STANDARD));
    23	        rooms.put(102, new Room(102, RoomType.STANDARD));
    24	        rooms.put(201, new Room(201, RoomType.DELUXE));
    25	        rooms.put(202, new Room(202, RoomType.DELUXE));
    26	        rooms.put(301, new Room(301, RoomType.SUITE));
    27	    }
