    37	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    38	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    39	                                        int guests, String ratePlanName, String companyCode) {
    40	        Room room = getRoom(roomNumber);
    41	        if (room == null) {
    42	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
    43	        }
    44	
    45	        if (checkIn.isAfter(checkOut) || checkIn.equals(checkOut)) {
    46	            throw new IllegalArgumentException("INVALID_REQUEST");
    47	        }
    48	
    49	        if (guests < 1) {
    50	            throw new IllegalArgumentException("INVALID_REQUEST");
    51	        }
    52	
    53	        if (guests > room.getCapacity()) {
    54	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
    55	        }
    56	
    57	        RatePlan ratePlan = RatePlanFactory.create(ratePlanName, companyCode);
    58	
    59	        try {
    60	            ratePlan.validate(room, checkIn, checkOut, guests, companyCode);
    61	        } catch (IllegalArgumentException e) {
    62	            throw new IllegalArgumentException("INVALID_REQUEST");
    63	        }
    64	
    65	        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
    66	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
    67	        }
    68	
    69	        int nights = DateUtils.countNights(checkIn, checkOut);
    70	        RatePlan.PriceCalculation prices = ratePlan.calculatePrices(room, checkIn, checkOut);
    71	
    72	        Reservation reservation = new Reservation(
    73	            nextReservationId++,
    74	            roomNumber,
    75	            guestName,
    76	            guestEmail,
    77	            guestCpf,
    78	            checkIn,
    79	            checkOut,
    80	            guests,
    81	            ratePlanName,
    82	            nights,
    83	            prices.subtotal,
    84	            prices.discount,
    85	            prices.total
    86	        );
    87	
    88	        reservations.put(reservation.getId(), reservation);
    89	        return reservation;
    90	    }
