    96	    public boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    97	        return reservations.values().stream()
    98	            .filter(r -> r.getRoomNumber() == roomNumber)
    99	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   100	            .noneMatch(r -> overlaps(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   101	    }
   102	
   103	    private boolean overlaps(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
   104	        return start1.isBefore(end2) && start2.isBefore(end1);
   105	    }
   106	
   107	    public void confirmReservation(long id, double amountPaid) {
   108	        Reservation reservation = getReservation(id);
   109	        if (reservation == null) {
   110	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
   111	        }
   112	
   113	        if (reservation.getStatus() != ReservationStatus.PENDING) {
   114	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   115	        }
   116	
   117	        reservation.setStatus(ReservationStatus.CONFIRMED);
   118	        reservation.setAmountPaid(amountPaid);
   119	    }
   120	
   121	    public void checkIn(long id) {
   122	        Reservation reservation = getReservation(id);
   123	        if (reservation == null) {
   124	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
   125	        }
   126	
   127	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   128	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   129	        }
   130	
   131	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   132	    }
   133	
   134	    public void checkOut(long id) {
   135	        Reservation reservation = getReservation(id);
   136	        if (reservation == null) {
   137	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
   138	        }
   139	
   140	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   141	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   142	        }
   143	
   144	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   145	    }
   146	
   147	    public void cancelReservation(long id, RatePlan ratePlan) {
   148	        Reservation reservation = getReservation(id);
   149	        if (reservation == null) {
   150	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
   151	        }
   152	
   153	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   154	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   155	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
   156	        }
   157	
   158	        reservation.setStatus(ReservationStatus.CANCELLED);
   159	        double refund = ratePlan.calculateRefund(reservation.getAmountPaid());
   160	        reservation.setRefund(Money.round(refund));
   161	    }
   162	
   163	    public List<Reservation> getReservationsForRoom(int roomNumber, LocalDate date) {
   164	        return reservations.values().stream()
   165	            .filter(r -> r.getRoomNumber() == roomNumber)
   166	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   167	            .filter(r -> r.getCheckIn().compareTo(date) <= 0 && r.getCheckOut().compareTo(date) > 0)
   168	            .collect(Collectors.toList());
   169	    }
   170	
   171	    public List<Reservation> getReservationsStartingInMonth(java.time.YearMonth month) {
   172	        return reservations.values().stream()
   173	            .filter(r -> DateUtils.getYearMonth(r.getCheckIn()).equals(month))
   174	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED || r.getAmountPaid() > 0)
   175	            .sorted(Comparator.comparing(Reservation::getCheckIn).thenComparing(Reservation::getId))
   176	            .collect(Collectors.toList());
   177	    }
   178	}
