     3	import java.time.LocalDate;
     4	import java.time.YearMonth;
     5	import java.time.temporal.ChronoUnit;
     6	
     7	public class DateUtils {
     8	    public static int countNights(LocalDate checkIn, LocalDate checkOut) {
     9	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    10	    }
    11	
    12	    public static boolean isHighSeason(LocalDate date) {
    13	        int month = date.getMonthValue();
    14	        int day = date.getDayOfMonth();
    15	
    16	        // July or December 15 - February 28/29
    17	        if (month == 7) return true;
    18	        if (month == 12 && day >= 15) return true;
    19	        if (month >= 1 && month <= 2) return true;
    20	        return false;
    21	    }
    22	
    23	    public static boolean isFriday(LocalDate date) {
    24	        return date.getDayOfWeek().getValue() == 5;
    25	    }
    26	
    27	    public static boolean isSunday(LocalDate date) {
    28	        return date.getDayOfWeek().getValue() == 7;
    29	    }
    30	
    31	    public static LocalDate nextSunday(LocalDate friday) {
    32	        return friday.plusDays(2);
    33	    }
    34	
    35	    public static YearMonth getYearMonth(LocalDate date) {
    36	        return YearMonth.from(date);
    37	    }
    38	}
