186	                handleIllegalArgumentException(ctx, e.getMessage());
187	            } catch (Exception e) {
188	                handleException(ctx, e);
189	            }
190	        });
191	
192	        // GET /reservations/{id}/document
193	        app.get("/reservations/{id}/document", ctx -> {
194	            try {
195	                long id = Long.parseLong(ctx.pathParam("id"));
196	                Reservation reservation = reservationService.getReservation(id);
