201	
202	                if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
203	                    reservation.getStatus() != ReservationStatus.CHECKED_IN &&
204	                    reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
