266	    private static void validateCreateReservationRequest(CreateReservationRequest req) {
267	        if (req.roomNumber == null || req.guestName == null || req.guestEmail == null ||
268	            req.guestCpf == null || req.checkIn == null || req.checkOut == null ||
269	            req.guests == null || req.ratePlan == null) {
270	            throw new ApiException(400, "INVALID_REQUEST", "Missing required fields");
271	        }
272	    }
273	
274	    private static void handleIllegalArgumentException(io.javalin.http.Context ctx, String message) {
275	        if (message.equals("ROOM_NOT_FOUND")) {
276	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
277	        } else if (message.equals("ROOM_UNAVAILABLE")) {
278	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
279	        } else if (message.equals("CAPACITY_EXCEEDED")) {
280	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
281	        } else if (message.equals("OPERATION_NOT_ALLOWED")) {
282	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current reservation state"));
283	        } else if (message.equals("RESERVATION_NOT_FOUND")) {
284	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
285	        } else {
286	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", message));
287	        }
288	    }
289	
290	    private static void handleApiException(io.javalin.http.Context ctx, ApiException e) {
291	        ctx.status(e.getStatusCode())
292	           .json(new ErrorResponse(e.getErrorCode(), e.getMessage()));
293	    }
294	
295	    private static void handleException(io.javalin.http.Context ctx, Exception e) {
296	        ctx.status(400)
297	           .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
298	    }
299	}
