    20	    public String generateOccupancyReport(LocalDate date) {
    21	        StringBuilder csv = new StringBuilder();
    22	        csv.append("room,type,reservation,check_in,check_out\n");
    23	
    24	        int occupiedCount = 0;
    25	
    26	        for (Room room : reservationService.getAllRooms()) {
    27	            List<Reservation> reservations = reservationService.getReservationsForRoom(room.getNumber(), date);
    28	            if (!reservations.isEmpty()) {
    29	                Reservation res = reservations.get(0);
    30	                csv.append(room.getNumber()).append(",");
    31	                csv.append(room.getType().getName()).append(",");
    32	                csv.append(res.getId()).append(",");
    33	                csv.append(res.getCheckIn().format(DATE_FORMAT)).append(",");
    34	                csv.append(res.getCheckOut().format(DATE_FORMAT)).append("\n");
    35	                occupiedCount++;
    36	            }
    37	        }
    38	
    39	        csv.append("total,").append(occupiedCount).append("/5\n");
    40	        return csv.toString();
    41	    }
    42	
    43	    public String generateRevenueReport(YearMonth month) {
    44	        StringBuilder csv = new StringBuilder();
    45	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    46	
    47	        double total = 0.0;
    48	
    49	        List<Reservation> reservations = reservationService.getReservationsStartingInMonth(month);
    50	        for (Reservation res : reservations) {
    51	            double amount = calculateAmount(res);
    52	            if (amount > 0) {
    53	                csv.append(res.getId()).append(",");
    54	                csv.append(res.getRoomNumber()).append(",");
    55	                csv.append(res.getCheckIn().format(DATE_FORMAT)).append(",");
    56	                csv.append(res.getCheckOut().format(DATE_FORMAT)).append(",");
    57	                csv.append(res.getStatus().toString()).append(",");
    58	                csv.append(Money.formatForCsv(amount)).append("\n");
    59	                total += amount;
    60	            }
    61	        }
    62	
    63	        csv.append("total,,,,").append(Money.formatForCsv(total)).append("\n");
    64	        return csv.toString();
    65	    }
    66	
    67	    private double calculateAmount(Reservation res) {
    68	        double amount = res.getAmountPaid();
    69	        if (res.getRefund() != null) {
    70	            amount -= res.getRefund();
    71	        }
    72	        return amount;
    73	    }
    74	}
